from taf.vran.vdu.enb.rest.client import HttpClient
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails
from taf.vran.vdu.enb.rest.utilities.poll_status import wait_for_reset_vdu_completion


class CPCONFIGv1(HttpClient):
    def __init__(self, base_url: str, connection_details: ConnectionDetails) -> None:
        super(CPCONFIGv1, self).__init__(connection_details)
        self.base_url = base_url + "/api/cp-config/v1"

    def reset_vdu(self, graceful_cell_shutdown: bool, wait_for_completion: bool, timeout: int) -> dict:
        """
        Reset the 4G vDU. When wait_for_completion is set to False, reset will be triggered and
        operation info returned. Otherwise, this keyword will wait until reset is completed.
        Operation is treated as completed when after resetting vDU is available again and error with code 404
        is raised meaning that this operation ID is no longer recognized.

        .. note::
            API endpoints used:
            1. vDU reset trigger: POST /api/cp-config/v1/vdu/operations/resets
            2. vDU reset operation status check: GET /api/cp-config/v1/vdu/operations/resets/{operationId}

        :param bool graceful_cell_shutdown: If True, the cells will be gracefully deactivated.
        :param bool wait_for_completion: If True, the function will wait for the reset to complete.
                                         If False, the function will return immediately after sending the trigger request.
                                         In such case get_reset_vdu_operation_status keyword can be used to check status.
                                         Defaults to True.
        :param int timeout: timeout for the reset operation to complete.

        :returns: operation info, for example:

        .. code-block:: python

            {
              "id": 101,
              "links": [
                {
                  "rel": "self",
                  "href": "/some/useful/links"
                }
              ],
              "status": "ongoing",
              "detailedStatuses": [
                {
                  "id": "1",
                  "status": "failed",
                  "errorText": "reset is already progressing"
                },
                {
                  "id": "2",
                  "status": "success"
                }
              ],
              "errorMessage": "error message",
              "errorCode": {
                "code": "user_restricted"
              }
            }
        :rtype: dict
        """
        trigger_vdu_reset_response = self.send_request(
            method="POST",
            endpoint="/vdu/operations/resets",
            headers=self.headers.get(accept="json", content_type="json"),
            data={"gracefulCellShutdown": graceful_cell_shutdown}
        )

        if wait_for_completion:
            return wait_for_reset_vdu_completion(
                instance=self,
                timeout=timeout,
                operation_id=trigger_vdu_reset_response["id"]
            )

        return trigger_vdu_reset_response

    def get_reset_vdu_operation_status(self, operation_id: str) -> dict:
        """
        Get status of reset vDU operation triggered by reset_vdu keyword.

        .. note::
            API endpoint used: GET /api/cp-config/v1/vdu/operations/resets/{operationId}

        :param operation_id: ID of reset vDU operation, can be taken from field "id" of reset_vdu output

        :returns: operation info, for example:

        .. code-block:: python

            {
              "id": 101,
              "links": [
                {
                  "rel": "self",
                  "href": "/some/useful/links"
                }
              ],
              "status": "ongoing",
              "detailedStatuses": [
                {
                  "id": "1",
                  "status": "failed",
                  "errorText": "reset is already progressing"
                },
                {
                  "id": "2",
                  "status": "success"
                }
              ],
              "errorMessage": "error message",
              "errorCode": {
                "code": "user_restricted"
              }
            }
        :rtype: dict
        """
        return self.send_request(method="GET", endpoint=f"/vdu/operations/resets/{operation_id}")
